BEGIN; SET LOCAL lock_timeout='10s'; SET LOCAL statement_timeout='60s';
DO $$ BEGIN IF current_database()<>'ems_cloud_v2_proto' THEN RAISE EXCEPTION 'Wrong database'; END IF; END $$;
SELECT pg_advisory_xact_lock(hashtextextended('SIM-SH-001',0));
UPDATE station_design_node SET grid_device_id=(SELECT id FROM device WHERE station_id=(SELECT id FROM station WHERE code='SIM-SH-001') AND code='GRID-01') WHERE device_id=(SELECT id FROM device WHERE station_id=(SELECT id FROM station WHERE code='SIM-SH-001') AND code='M-01') AND grid_device_id IS NULL;
COMMIT;
