INSERT INTO member_grant_station(grant_id,station_id) SELECT DISTINCT g.id,s.id FROM member_grant g JOIN member_grant_station old ON old.grant_id=g.id JOIN station h ON h.id=old.station_id AND h.code='PROTO-001' JOIN app_role r ON r.id=g.role_id JOIN station s ON s.code='SIM-SH-001' AND s.organization_id=r.organization_id WHERE g.valid_until IS NULL ON CONFLICT DO NOTHING;
INSERT INTO audit_event(action,detail) SELECT 'simulation.station.create','SIM-SH-001: supplied topology export; no physical hardware connected' WHERE NOT EXISTS(SELECT 1 FROM audit_event WHERE action='simulation.station.create' AND detail LIKE 'SIM-SH-001:%');
